function ms = gtd_make_multisine(record, plant, cfg)
% GTD_MAKE_MULTISINE  Injected stage force for one record.
%   ms = GTD_MAKE_MULTISINE(record, plant, cfg) returns a struct:
%     ms.f_stage  (N x 3)  stage force [F_X1, F_X2, F_Y] to inject at plant input
%     ms.A        (1 x 3)  applied logical amplitudes [A_sym, A_anti(torque), A_Y]
%     ms.info     struct   provenance (seed, band, per-channel crest factors, ...)
%
%   Excitation type comes from record.p.excitation:
%     'multisine' : 3 independent random-phase multisines in LOGICAL channels
%                   [f_sym, f_anti, f_Y], period = full record, low-crest-factor
%                   selection (best of N), seeded + cached. CF is scored on the
%                   constrained quantity: f_sym/f_Y on their own signal (stage
%                   force is a uniform scaling), f_anti on the closed-loop yaw
%                   response. Amplitudes: A_sym/A_Y fixed (GATE-2), A_anti sized
%                   to the yaw budget. Transformed to stage via P^{-1}.
%     'sinesweep' : force chirp on f_Y over the active window (E1).
%     'none'      : zero force (E4 regression check).
%
%   Spec: docs/trajectory-generation-spec-draft.md sections 1.4-1.9, 5.

    N = cfg.N_record;
    switch record.p.excitation
        case 'none'
            ms = pack(zeros(N,3), [0 0 0], struct('excitation','none'));
            return
        case 'sinesweep'
            ms = make_sinesweep(record, cfg);
            return
    end

    % ── multisine: reuse cached unit realization if params match ────────────
    [ok, f_unit] = load_cache(record, cfg);
    if ~ok
        f_unit = select_multisine(record, plant, cfg);
        save_cache(record, cfg, f_unit);
    end

    % ── amplitudes: A_sym/A_Y fixed; A_anti sized to the yaw budget ─────────
    A_anti    = gtd_size_anti_amp(f_unit(:,2), plant, cfg);
    A         = record.p.amp_frac * [cfg.A_sym, A_anti, cfg.A_Y];
    f_logical = f_unit .* A;                        % (N x 3) .* (1 x 3)
    f_stage   = gtd_logical_to_stage(f_logical, cfg);

    ms = pack(f_stage, A, struct('excitation','multisine', 'seed',record.seed, ...
              'band',[cfg.f_low cfg.f_high], 'A_anti',A_anti));
end

% ── multisine synthesis and crest-factor selection ──────────────────────────

function f_unit = select_multisine(record, plant, cfg)
% Draw n candidates per logical channel and keep the lowest-crest-factor one.
    N     = cfg.N_record;
    df    = cfg.fs / N;
    freqs = cfg.f_low : df : cfg.f_high;
    bins  = round(freqs / df) + 1;                 % lines fall exactly on FFT bins
    H_yaw = [1 -1 0] * plant.sys_cl * ([1; -1; 0] / cfg.Lb);

    rng(record.seed);                              % reproducible per-record draw
    sym = []; anti = []; Yc = [];
    cf_sym = Inf; cf_anti = Inf; cf_Y = Inf;
    for ic = 1:cfg.n_ms_candidates
        xs = synth(bins, N);
        xa = synth(bins, N);
        xy = synth(bins, N);
        cs = max(abs(xs));                         % unit RMS -> CF = peak
        cy = max(abs(xy));
        yaw = lsim(H_yaw, xa);  ca = max(abs(yaw)) / rms(yaw);   % constrained CF for anti
        if cs < cf_sym,  sym  = xs;  cf_sym  = cs;  end
        if ca < cf_anti, anti = xa;  cf_anti = ca;  end
        if cy < cf_Y,    Yc   = xy;  cf_Y    = cy;  end
    end
    f_unit = [sym, anti, Yc];
end

function x = synth(bins, N)
% One unit-RMS random-phase multisine via IFFT (flat magnitude on the band).
    X = zeros(N,1);
    X(bins) = exp(1j * 2*pi * rand(numel(bins),1));
    x = ifft(X, 'symmetric');
    x = x / rms(x);
end

function ms = make_sinesweep(record, cfg)
% Linear force chirp on f_Y over the active window (E1), tapered at both ends.
    N = cfg.N_record;  n_a = cfg.n_active;  t_a = (0:n_a-1)' * cfg.ts;
    b   = record.p.sweep_band;  f0 = b(1);  f1 = b(2);  T = t_a(end);
    amp = record.p.amp_frac * cfg.A_Y * sqrt(2);           % peak; RMS ~ amp_frac*A_Y
    phase = 2*pi * (f0*t_a + (f1 - f0)/(2*T) * t_a.^2);    % linear instantaneous freq

    % Half-cosine fade in/out (0.5 s) so the chirp does not slam the system on/off.
    % An abrupt start/stop kicks all modes -> large onset/offset transients that bury
    % the resonance response. Same taper idea as make_ref_oscillatory.
    n_fade = round(0.5 / cfg.ts);
    win = ones(n_a, 1);
    ramp = 0.5 * (1 - cos(pi * (0:n_fade-1)' / n_fade));
    win(1:n_fade)         = ramp;
    win(end-n_fade+1:end) = flipud(ramp);

    f_logical = zeros(N, 3);
    f_logical(cfg.n_hold + (1:n_a), 3) = amp * win .* sin(phase);   % on f_Y, active window
    f_stage = gtd_logical_to_stage(f_logical, cfg);
    ms = pack(f_stage, [0, 0, amp/sqrt(2)], struct('excitation','sinesweep', 'band',b));
end

function ms = pack(f_stage, A, info)
    ms = struct('f_stage', f_stage, 'A', A, 'info', info);
end

% ── per-record cache (keyed by seed/band/period/operating point) ────────────

function f = cache_path(record, cfg)
    f = fullfile(cfg.out_dir, '_cache', ['ms_' record.id '.mat']);
end

function [ok, f_unit] = load_cache(record, cfg)
    ok = false;  f_unit = [];
    f = cache_path(record, cfg);
    if exist(f, 'file')
        C = load(f);
        if isfield(C,'info') && C.info.seed == record.seed && ...
           isequal(C.info.band, [cfg.f_low cfg.f_high]) && ...
           C.info.N == cfg.N_record && C.info.Yop == record.Y_op && ...
           C.info.n_cand == cfg.n_ms_candidates
            ok = true;  f_unit = C.f_unit;
        end
    end
end

function save_cache(record, cfg, f_unit)
    d = fileparts(cache_path(record, cfg));
    if ~exist(d, 'dir'), mkdir(d); end
    info = struct('seed',record.seed, 'band',[cfg.f_low cfg.f_high], ...
                  'N',cfg.N_record, 'Yop',record.Y_op, 'n_cand',cfg.n_ms_candidates);
    save(cache_path(record, cfg), 'f_unit', 'info');
end
function records = gtd_build_records(cfg)
% GTD_BUILD_RECORDS  Declarative table of the 22 records (T1-14, V1-4, E1-4).
%   records = GTD_BUILD_RECORDS(cfg) returns a 1x22 struct array. Each element
%   is pure data describing one record; no simulation logic here.
%
%   Common fields: id, split, class, Y_op, seed, p
%     class : 'standstill' | 'oscillatory' | 'aprbs'
%             (the six spec "classes" collapse to three reference SHAPES;
%              y-sweep and lissajous are just oscillatory parameterizations,
%              and E1's sinesweep is a standstill motion with a swept excitation)
%     Y_op  : frozen operating point for the controller (D-039 convention)
%     seed  : 100*track_id + index  (independent realization per record & split)
%     p     : class-specific geometry + excitation control
%             excitation : 'multisine' | 'sinesweep' | 'none'
%             amp_frac   : excitation amplitude scale vs track level (test set uses 0.80)
%
%   Ladder margins are DERIVED from cfg.lim so records and cfg cannot disagree:
%     training top (T11) = 75% of the enforced per-axis limits   (HEURISTIC, user-set)
%     test extrapolation (E3) = 90% of the enforced per-axis limits
%
%   Spec: docs/trajectory-generation-spec-draft.md sections 3, 4, 5.

    L = cfg.lim;
    base75 = struct('vmax_X',0.75*L.vel,'amax_X',0.75*L.acc_X,'vmax_Y',0.75*L.vel,'amax_Y',0.75*L.acc_Y);
    base90 = struct('vmax_X',0.90*L.vel,'amax_X',0.90*L.acc_X,'vmax_Y',0.90*L.vel,'amax_Y',0.90*L.acc_Y);
    lad = @(b,f) struct('vmax_X',f*b.vmax_X,'amax_X',f*b.amax_X,'vmax_Y',f*b.vmax_Y,'amax_Y',f*b.amax_Y);

    % Setpoint ranges (logical coords) for the APRBS class
    Xs_full = [-0.10, 0.10];  Xs_red = [-0.05, 0.05];
    Xa_off  = [0, 0];         Xa_on  = [-0.001, 0.001];   % X_anti active only where the 6mm budget allows
    Yr_full = [-0.30, 0.30];  Yr_v2  = [-0.30, -0.14];

    c = {};   % cell list, converted to struct array at the end

    % ── T1-T5: standstill multisine at 5 frozen-Y points (>=3 for quadratic M(Y)) ─
    c{end+1} = mk('T1_standstill_Ym30','train','standstill',-0.30, ps());
    c{end+1} = mk('T2_standstill_Ym15','train','standstill',-0.15, ps());
    c{end+1} = mk('T3_standstill_Y000','train','standstill', 0.00, ps());
    c{end+1} = mk('T4_standstill_Yp15','train','standstill', 0.15, ps());
    c{end+1} = mk('T5_standstill_Yp30','train','standstill', 0.30, ps());

    % ── T6-T8: Y-sweeps (scheduling-rate coverage) ──────────────────────────
    c{end+1} = mk('T6_ysweep_slow', 'train','oscillatory', 0.00, po(0.00, 0,0,    0,0,   0.30,0.2));
    c{end+1} = mk('T7_ysweep_fast', 'train','oscillatory', 0.00, po(0.00, 0,0,    0,0,   0.30,0.7));
    c{end+1} = mk('T8_ysweep_xmix', 'train','oscillatory', 0.00, po(0.00, 0.05,1.1, 0,0, 0.30,0.35));

    % ── T9-T12: randomized jerk-limited setpoint sequences (position-level APRBS) ─
    c{end+1} = mk('T9_aprbs_30',  'train','aprbs', 0.00, pa(lad(base75,0.30), 0.050, Xs_full, Xa_off, Yr_full));
    c{end+1} = mk('T10_aprbs_60', 'train','aprbs', 0.00, pa(lad(base75,0.60), 0.035, Xs_full, Xa_off, Yr_full));
    c{end+1} = mk('T11_aprbs_100','train','aprbs', 0.00, pa(lad(base75,1.00), 0.025, Xs_full, Xa_off, Yr_full));
    c{end+1} = mk('T12_aprbs_yaw','train','aprbs', 0.00, pa(lad(base75,0.60), 0.040, Xs_red,  Xa_on,  Yr_full));

    % ── T13-T14: lissajous (multi-axis simultaneous) ────────────────────────
    c{end+1} = mk('T13_lissajous', 'train','oscillatory', 0.00, po(0.00, 0.08,1.5, 0,0,      0.25,0.4));
    c{end+1} = mk('T14_lissajous_yaw','train','oscillatory', 0.00, po(0.00, 0.06,1.3, 0.001,0.8, 0.30,0.7));

    % ── V1-V4: validation (separate generation, fresh seeds, unseen interior Y) ─
    c{end+1} = mk('V1_standstill_Yp10','val','standstill', 0.10, ps());
    c{end+1} = mk('V2_aprbs_Ylow',     'val','aprbs',     -0.22, pa(lad(base75,0.60), 0.035, Xs_full, Xa_off, Yr_v2));
    c{end+1} = mk('V3_ysweep_Yp10',    'val','oscillatory', 0.10, po(0.10, 0,0,    0,0,   0.15,0.2));
    c{end+1} = mk('V4_lissajous_Ym10', 'val','oscillatory',-0.10, po(-0.10, 0.07,1.4, 0,0, 0.20,0.5));

    % ── E1-E4: test (held out until final evaluation) ───────────────────────
    % E1's sweep band now FOLLOWS cfg, it is no longer a literal. It used to be [130 180],
    % the one excitation band in the generator that ignored cfg.f_low/cfg.f_high, so
    % BAND_OVERRIDE in generate_trajectory_data.m never reached it (gtd_make_multisine.m:86
    % reads record.p.sweep_band; every other record type reads cfg at line 54). That literal
    % targets the absorber's STANDALONE fa = 150 Hz, but the mode that exists is the free-free
    % two-mass root fa*sqrt(1 + ma/mh_rigid): 158.11 Hz at ma_frac = 0.10 and 212.13 Hz at 0.50.
    % A "resonance sweep" that misses the resonance by 32 Hz and sits on the anti-resonance is
    % not the record this row is meant to produce.
    % BACKWARD COMPATIBLE on the track it was written for: TRACK='augmentation' at ma_frac 0.10
    % with no override gives cfg.f_low/f_high = 130/180, i.e. exactly the old literal.
    % CHANGES E1 on TRACK='joint'/'joint_lowf', where cfg is [1,200] or [0.083,200] rather than
    % [130,180]. Records already on disk are untouched; only a regeneration would differ.
    c{end+1} = mk('E1_resonance_sweep','test','standstill', 0.00, ...
                  psweep([cfg.f_low cfg.f_high], 0.80));
    c{end+1} = mk('E2_multisine_Yp22', 'test','standstill', 0.22, ps(0.80));
    c{end+1} = mk('E3_aprbs_above',    'test','aprbs',      0.00, pa(lad(base90,1.00), 0.030, Xs_full, Xa_off, Yr_full));
    c{end+1} = mk('E4_multisine_off',  'test','aprbs',      0.00, pnone(pa(lad(base75,1.00), 0.025, Xs_full, Xa_off, Yr_full)));

    % ── Assign per-record seeds and materialize the struct array ────────────
    records = [c{:}];
    for k = 1:numel(records)
        records(k).seed = 100*cfg.track_id + k;   % independent draw per record AND split
    end
end

% ── local builders ──────────────────────────────────────────────────────────

function r = mk(id, split, class, Y_op, p)
    r = struct('id',id, 'split',split, 'class',class, 'Y_op',Y_op, 'seed',0, 'p',p);
end

function p = ps(amp_frac)            % standstill params
    if nargin < 1, amp_frac = 1.0; end
    p = struct('excitation','multisine', 'amp_frac',amp_frac);
end

function p = psweep(band, amp_frac)  % standstill with swept-force excitation (E1)
    p = struct('excitation','sinesweep', 'amp_frac',amp_frac, 'sweep_band',band);
end

function p = po(Y_center, A_sym, f_sym, A_anti, f_anti, A_y, f_y)   % oscillatory params
    p = struct('Y_center',Y_center, 'A_sym',A_sym, 'f_sym',f_sym, ...
               'A_anti',A_anti, 'f_anti',f_anti, 'A_y',A_y, 'f_y',f_y, ...
               'excitation','multisine', 'amp_frac',1.0);
end

function p = pa(lvl, jerkTime, X_sym_range, X_anti_range, Y_range)  % aprbs params
    p = lvl;
    p.jerkTime     = jerkTime;
    p.X_sym_range  = X_sym_range;
    p.X_anti_range = X_anti_range;
    p.Y_range      = Y_range;
    p.excitation   = 'multisine';
    p.amp_frac     = 1.0;
end

function p = pnone(p)                % turn the injected excitation off (E4)
    p.excitation = 'none';
end
function out = gtd_run_simulation(record, r, t, f_stage, plant, cfg)
% GTD_RUN_SIMULATION  Run the Simulink model for one record (the only impure fn).
%   out = GTD_RUN_SIMULATION(record, r, t, f_stage, plant, cfg) simulates the
%   gantry model with (and, for the MSD model, without) the injected multisine,
%   and returns the reconstructed signals.
%
%   Simulink resolves variables from the BASE workspace, so all model inputs are
%   pushed to base with assignin and the run is launched with evalin. This is the
%   proven interface of generate_oscillatory_multisine_data.m; all base-workspace
%   contact is contained in this one function.
%
%   Returned struct: t_sim, r_sim, f_ms, q_with, u_fb, u_total, and (MSD only)
%   da_with, q_without, da_without.

    % ── push constant parameters and the frozen plant to the base workspace ──
    push_params(cfg);
    assignin('base', 'Cfb',    plant.Cfb);
    assignin('base', 'Cfb_ss', plant.Cfb);
    assignin('base', 'G',      plant.G);
    assignin('base', 'sys',    plant.sys);
    assignin('base', 'sys_cl', plant.sys_cl);
    assignin('base', 'T_cl',   plant.T_cl);
    assignin('base', 'r', r);
    assignin('base', 't', t);
    assignin('base', 'Y', plant.Y_op);

    tend = t(end);

    % ── WITH multisine ──────────────────────────────────────────────────────
    [q_aug, da] = run_once(f_stage, cfg, tend);
    [t_sim, r_sim, f_ms, q_with, da_with] = resample_sim(q_aug, da, r, f_stage, t);

    u_fb    = lsim(plant.Cfb, r_sim - q_with);
    u_total = u_fb + f_ms;

    out = struct('t_sim',t_sim, 'r_sim',r_sim, 'f_ms',f_ms, ...
                 'q_with',q_with, 'u_fb',u_fb, 'u_total',u_total);

    % ── WITHOUT multisine (informativeness baseline; MSD model only) ─────────
    if cfg.use_msd
        out.da_with = da_with;
        [q_aug0, da0] = run_once(zeros(size(f_stage)), cfg, tend);
        [~, ~, ~, q_without, da_without] = resample_sim(q_aug0, da0, r, zeros(size(f_stage)), t);
        out.q_without  = q_without;
        out.da_without = da_without;
    end
end

% ── helpers ─────────────────────────────────────────────────────────────────

function [q_aug, da] = run_once(f, cfg, tend)
% One Simulink run with force f. Swaps the payload mass to the rigid part so the
% hidden MSD (ma) enters only through the extra state, then restores it.
    assignin('base', 'f', f);
    if cfg.use_msd, assignin('base', 'mh', cfg.mh_rigid); end
    evalin('base', sprintf('sim(''%s'', %.12g);', cfg.mdl, tend));
    if cfg.use_msd, assignin('base', 'mh', cfg.mh); end
    if cfg.use_msd
        % q_aug is the output of the 'Extended ODE' block (gantrySystemExtended.m,
        % 8-state), whose own absorber state Simulink logs as delta_a_ode. The plain
        % 'delta_a' variable is outport 4 of the Simscape Multibody 'Single H-gantry'
        % subsystem, i.e. a DIFFERENT plant (it retains the Coriolis/centrifugal terms
        % that gantrySystemExtended drops by freezing M), so pairing it with q_aug made
        % the saved record internally inconsistent. Read the ODE's own state instead.
        % gtd_save_record derives vdelta_a as gradient(da, ts), so it follows this fix.
        q_aug = evalin('base', 'q_aug');
        da    = evalin('base', 'delta_a_ode');
    else
        q_aug = evalin('base', 'q1');
        da    = zeros(size(q_aug,1), 1);
    end
end

function push_params(cfg)
    names = {'mb','mh','m1','m2','Jb','Jh','cg1','cg2','cy','cb1','cb2', ...
             'kb1','kb2','Lb','Lh','d','cc1','cc2','ccy','n','P','C_damp','K','fs','ts','fbw'};
    for k = 1:numel(names), assignin('base', names{k}, cfg.(names{k})); end
    if cfg.use_msd
        msd = {'ma_frac','ma','mh_rigid','L0','fa','ka','zeta_a','ca'};
        for k = 1:numel(msd), assignin('base', msd{k}, cfg.(msd{k})); end
        assignin('base', 'mh_original', cfg.mh);   % full payload mass (model MATLAB Function refs it)
    end
end

function [t_sim, r_sim, f_sim, q_sim, da_sim] = resample_sim(q_aug, delta_a, r, f, t)
% Handle variable-step Simulink output via interpolation onto a uniform grid.
    Ns = size(q_aug, 1);
    if Ns ~= numel(t)
        t_sim = linspace(0, t(end), Ns)';
        r_sim = interp1(t, r, t_sim);
        f_sim = interp1(t, f, t_sim);
    else
        t_sim = t;  r_sim = r;  f_sim = f;
    end
    q_sim  = q_aug;
    da_sim = delta_a;
end

